pageCss:
:root{--color-accent:#2451B8;--color-accent-hover:#1B3F92;--color-bg-light:#F5F4F0;--color-border:#D6D3CB;--color-text-primary:#15181F}
html{scroll-behavior:smooth}
html,body{margin:0;background:#F5F4F0;color:#15181F;font-family:'Inter',sans-serif;-webkit-font-smoothing:antialiased}
a{color:#2451B8;text-decoration:none}a:hover{color:#1B3F92}
*{box-sizing:border-box}
@keyframes wpPulse{0%,100%{opacity:.35}50%{opacity:1}}
@keyframes wpRing{0%{transform:translate(-50%,-50%) scale(.6);opacity:.8}100%{transform:translate(-50%,-50%) scale(1.8);opacity:0}}
@keyframes wpTravel{0%{left:0%;opacity:0}10%{opacity:1}90%{opacity:1}100%{left:100%;opacity:0}}
@keyframes wpGrow{0%,15%{width:18%}55%,100%{width:var(--w,80%)}}
@keyframes wpLit{0%,100%{background:#232833}40%,60%{background:#2451B8}}
@keyframes wpRow{0%{transform:translateY(0)}100%{transform:translateY(-34px)}}
@keyframes wpBlink{0%,100%{box-shadow:0 0 0 0 rgba(143,170,232,.6)}50%{box-shadow:0 0 0 8px rgba(143,170,232,0)}}
@keyframes wpChuckle{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-3px) rotate(-2deg)}}
@keyframes wpTapR{0%,100%{transform:rotate(0deg)}50%{transform:rotate(10deg)}}
@keyframes wpCheer{0%,100%{transform:translateY(0)}40%{transform:translateY(-14px)}}
@keyframes wpTap{0%,100%{transform:rotate(0deg)}50%{transform:rotate(-18deg)}}
@keyframes wpHop{0%,100%{transform:translateY(0)}30%{transform:translateY(-16px)}55%{transform:translateY(0)}75%{transform:translateY(-6px)}}
@keyframes wpEyeBlink{0%,93%,100%{transform:scaleY(1)}96%{transform:scaleY(0.1)}}
@keyframes wpShake{0%,100%{transform:rotate(0deg)}25%{transform:rotate(-8deg)}75%{transform:rotate(8deg)}}
@keyframes wpBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
@keyframes wpArrow{0%,100%{transform:translateY(-2px)}50%{transform:translateY(4px)}}
@keyframes wpWave{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}
@keyframes wpType{0%,20%{width:0}60%,100%{width:70%}}
